"use client";

import { type ClipboardEvent, type HTMLAttributes, type KeyboardEvent, useId, useRef, useState } from "react";
import { cx } from "../utils/cx";

export type PinInputProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  /** Names the field (e.g. "Verification code"). Each box is announced as "digit N of M". */
  "aria-label": string;
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Called once every box is filled. */
  onComplete?: (value: string) => void;
  type?: "numeric" | "alphanumeric";
  /** Hide the characters, like a password. */
  mask?: boolean;
  disabled?: boolean;
  invalid?: boolean;
};

/** A one-time-code field of separate boxes: typing advances, Backspace goes back, arrows move, paste fills them all. */
export function PinInput({
  length = 6,
  value: controlled,
  defaultValue = "",
  onValueChange,
  onComplete,
  type = "numeric",
  mask,
  disabled,
  invalid,
  className,
  ...rest
}: PinInputProps) {
  const [inner, setInner] = useState(defaultValue.slice(0, length));
  const value = (controlled ?? inner).slice(0, length);
  const boxes = useRef<Array<HTMLInputElement | null>>([]);
  const base = useId();
  const allowed = (c: string) => (type === "numeric" ? /^[0-9]$/.test(c) : /^[a-zA-Z0-9]$/.test(c));
  const set = (next: string) => {
    if (controlled === undefined) setInner(next);
    onValueChange?.(next);
    if (next.length === length) onComplete?.(next);
  };
  const focus = (i: number) => boxes.current[Math.max(0, Math.min(length - 1, i))]?.focus();
  const put = (i: number, chars: string) => {
    const clean = Array.from(chars).filter(allowed);
    if (!clean.length) return;
    const arr = value.padEnd(length, " ").split("");
    let at = i;
    for (const c of clean) {
      if (at >= length) break;
      arr[at++] = c;
    }
    set(arr.join("").replace(/ +$/, "").replace(/ /g, ""));
    focus(Math.min(at, length - 1));
  };
  const key = (i: number) => (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Backspace") {
      e.preventDefault();
      const chars = value.split("");
      if (chars[i]) {
        chars.splice(i, 1);
        set(chars.join(""));
      } else if (i > 0) {
        chars.splice(i - 1, 1);
        set(chars.join(""));
        focus(i - 1);
      }
    } else if (e.key === "Delete") {
      e.preventDefault();
      const chars = value.split("");
      chars.splice(i, 1);
      set(chars.join(""));
    } else if (e.key === "ArrowLeft") {
      e.preventDefault();
      focus(i - 1);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      focus(i + 1);
    } else if (e.key === "Home") {
      e.preventDefault();
      focus(0);
    } else if (e.key === "End") {
      e.preventDefault();
      focus(length - 1);
    }
  };
  const paste = (i: number) => (e: ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault();
    put(i, e.clipboardData.getData("text"));
  };
  return (
    <div {...rest} role="group" className={cx("hm-pin", className)} data-invalid={invalid ? "" : undefined}>
      {Array.from({ length }, (_, i) => (
        <input
          key={i}
          ref={(el) => {
            boxes.current[i] = el;
          }}
          id={`${base}-${i}`}
          className="hm-pin-box hm-control"
          type={mask ? "password" : "text"}
          inputMode={type === "numeric" ? "numeric" : "text"}
          autoComplete={i === 0 ? "one-time-code" : "off"}
          aria-label={`${rest["aria-label"]}, digit ${i + 1} of ${length}`}
          aria-invalid={invalid || undefined}
          maxLength={2}
          disabled={disabled}
          value={value[i] ?? ""}
          onChange={(e) => {
            const v = e.target.value;
            // a box holds one character: when it already has one, the newly typed character is the other one
            put(i, v.length > 1 ? v.replace(value[i] ?? "", "").slice(-1) || v.slice(-1) : v);
          }}
          onKeyDown={key(i)}
          onPaste={paste(i)}
          onFocus={(e) => e.currentTarget.select()}
        />
      ))}
    </div>
  );
}
